import 'package:flutter/material.dart';import 'package:get/get.dart';import 'package:get_storage/get_storage.dart';import 'core/routes/app_routes.dart';import 'core/services/api_service.dart';import 'core/services/location_service.dart';import 'core/services/notification_service.dart';import 'core/services/socket_service.dart';import 'core/services/storage_service.dart';import 'core/theme/app_theme.dart';import 'modules/auth/controllers/auth_controller.dart';
Future<void> main() async {WidgetsFlutterBinding.ensureInitialized();await GetStorage.init();Get.put(StorageService(),permanent:true);await Get.putAsync(()=>ApiService().init(),permanent:true);Get.put(SocketService(),permanent:true);Get.put(LocationService(),permanent:true);Get.put(NotificationService(),permanent:true);final auth=Get.put(AuthController(),permanent:true);runApp(const RideApp());WidgetsBinding.instance.addPostFrameCallback((_)=>auth.restore());}
class RideApp extends StatelessWidget {const RideApp({super.key});@override Widget build(BuildContext context)=>GetMaterialApp(title:'Chalo Bhai',debugShowCheckedModeBanner:false,theme:AppTheme.light,initialRoute:AppRoutes.role,getPages:AppRoutes.pages);}
